mapper.insert:
INSERT INTO community_board (
title, category, content, user_id, origin_file_name, file_name, file_size, mode
)
VALUES (
#{title}, #{category}, #{content}, #{userId}, #{originFileName}, #{uuidFileName}, #{fileSize}, #{mode}
)

mapper.update:
UPDATE community_board
SET read_view = read_view + 1
WHERE post_id = #{postId}

mapper.select:
SELECT read_view
FROM community_board
WHERE post_id = #{postId}

SELECT u.username,post_id as postId, title,category,c.file_name as uuidFileName, content,read_view, c.created_at as createdAt, c.origin_file_name as originFileName,c.user_id as userId
FROM community_board c
JOIN users u ON c.user_id = u.id
WHERE category = #{category}
ORDER BY c.created_at DESC
LIMIT #{startPost}, #{postsPerPage}

SELECT COUNT(*)
FROM community_board
WHERE category = #{category}
